CREATE TABLE agent_run (created_at timestamp not null, updated_at timestamp not null, version bigint not null, conversation_id varchar(255) not null, error text, final_output text, goal text not null, id varchar(255) not null, model varchar(255) not null, request_json text, server varchar(255) not null, status varchar(255) not null check ((status in ('QUEUED','RUNNING','WAITING_FOR_APPROVAL','CANCEL_REQUESTED','COMPLETED','FAILED','CANCELLED'))), primary key (id));
CREATE TABLE agent_step (sequence integer not null, completed_at timestamp, created_at timestamp not null, id integer, agent_run_id varchar(255) not null, detail text, status varchar(255) not null check ((status in ('PENDING','RUNNING','COMPLETED','FAILED','SKIPPED'))), summary text not null, type varchar(255) not null check ((type in ('PLAN','MODEL','TOOL','APPROVAL','FINAL'))), primary key (id));
CREATE TABLE chat_message (seq integer not null, created_at timestamp not null, id integer, content text, conversation_id varchar(255) not null, images text, role varchar(255) not null, primary key (id));
CREATE TABLE conversation (num_ctx integer, summarized_count integer not null default 0, temperature float, created_at timestamp not null, updated_at timestamp not null, id varchar(255) not null, model varchar(255), server varchar(255), stop_sequences text, summary text, system_prompt text, title varchar(255) not null, web_session_id varchar(255), primary key (id));
